"""Islamiat (Ikhtiari) XII PDF65: pp.120–121 — ahadith 27 (end), 28, 29. Run: python class12_iski_page065.py"""
from class12_iski_common import BOOK, Builder, rec, P, L, AR


def p65():
    b = Builder()
    P(b, [('… grants understanding of the religion. To understand the wisdoms of the religion and to spend the days and nights of life with thought and understanding is very great wisdom. We should keep praying to Allah the Exalted that He grant us understanding of the religion in its correct sense and bless us with the good fortune of acting upon the Quran and the Sunnah.', 'دین کی سمجھ عطا کرتا ہے۔ دین کی حکمتوں کو سمجھنا اور سوچ سمجھ کر زندگی کے روز و شب گزارنا بہت بڑی دانائی ہے۔ اللہ تعالیٰ سے دعا کرتے رہنا چاہیے کہ وہ ہمیں صحیح معنوں میں دین کی سمجھ عطا فرمائے اور قرآن و سنت پر عمل کرنے کی سعادت بخشے۔', '… د دین پوهه ورکوي. د دین د حکمتونو پوهېدل او په فکر او پوهې د ژوند شپې او ورځې تېرول ډېر لوی حکمت دی. باید له الله تعالی دعا کوو چې موږ ته په سمه مانا د دین پوهه راکړي او پر قرآن او سنت د عمل سعادت راپه برخه کړي.')])
    b.h('Hadith no. 28', 'حدیث نمبر 28', 'حدیث نمبر ۲۸')
    AR(b, 'عَنْ عَبْدِ اللّٰهِ رَضِيَ اللّٰهُ عَنْهُ قَالَ سَاَلْتُ النَّبِيَّ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ اَيُّ الْعَمَلِ اَحَبُّ اِلَى اللّٰهِ عَزَّ وَجَلَّ؟ قَالَ: اَلصَّلٰوةُ عَلٰى وَقْتِهَا، قَالَ: ثُمَّ اَيٌّ؟ قَالَ: ثُمَّ بِرُّ الْوَالِدَيْنِ، قَالَ: ثُمَّ اَيٌّ؟ قَالَ: اَلْجِهَادُ فِيْ سَبِيْلِ اللّٰهِ', 'صحیح البخاری کتاب الادب حدیث نمبر ۵۹۷۰')
    b.p('Translation: It is narrated from Abdullah bin Mas\'ud (may Allah be pleased with him) that he says: I asked the Noble Prophet ﷺ which deed is most beloved to Allah. He ﷺ said: that prayer which is offered on time. He asked: then which? He ﷺ said: then doing good to parents. He asked: then which? He ﷺ said: striving (jihad) in the way of Allah.', 'ترجمہ: عبداللہ رضی اللہ عنہ بن مسعود سے روایت ہے فرماتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وآلہٖ وسلم سے سوال کیا کہ کونسا عمل اللہ کے نزدیک زیادہ محبوب ہے؟ آپ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا: وہ نماز جو وقت پر پڑھی جائے، فرمایا پھر کونسا؟ آپ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا: پھر والدین کے ساتھ نیکی کرنا، فرمایا پھر کونسا؟ آپ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا: اللہ کے راستے میں جہاد کرنا۔', 'ژباړه: له عبدالله بن مسعود رضي الله عنه روایت دی، وايي: ما له نبي اکرم ﷺ وپوښتل چې کوم عمل الله ته ډېر محبوب دی؟ هغه ﷺ وفرمایل: هغه لمونځ چې په وخت وکړل شي. ویې ویل: بیا کوم؟ هغه ﷺ وفرمایل: بیا له مور و پلار سره نېکي. ویې ویل: بیا کوم؟ هغه ﷺ وفرمایل: د الله په لاره کې جهاد.')
    b.h('Explanation', 'تشریح', 'تشریح')
    b.p('In this blessed hadith the Noble Prophet ﷺ has stated three such deeds which Allah the Exalted likes extremely:', 'اس حدیثِ مبارکہ میں نبی اکرم صلی اللہ علیہ وآلہٖ وسلم نے تین ایسے اعمال بیان فرمائے ہیں جو اللہ تعالیٰ کو بے حد پسند ہیں:', 'په دې مبارک حدیث کې نبي اکرم ﷺ درې داسې عملونه بیان کړي چې الله تعالی ته ډېر خوښ دي:')
    L(b, [('1. Offering prayer at the appointed time.', '۱۔ وقتِ مقررہ پر نماز ادا کرنا۔', '۱. په ټاکلي وخت لمونځ ادا کول.'),
          ('2. Treating parents well.', '۲۔ والدین کے ساتھ حسنِ سلوک کرنا۔', '۲. له مور و پلار سره ښه چلند.'),
          ('3. Striving (jihad) in the way of Allah the Exalted.', '۳۔ اللہ تعالیٰ کے راستے میں جہاد کرنا۔', '۳. د الله تعالی په لاره کې جهاد.')])
    b.p('In the Holy Quran the command most frequently given is that of offering prayer. Another blessed saying of the Noble Prophet ﷺ is also …', 'قرآن مجید میں سب سے زیادہ نماز کی ادائیگی کا ہی حکم آیا ہے۔ نبی اکرم صلی اللہ علیہ وآلہٖ وسلم کا ایک اور', 'په قرآن مجید کې تر ټولو ډېر د لمانځه د ادا کولو حکم راغلی. د نبي اکرم ﷺ یو بل مبارک ارشاد هم …')
    r1 = rec(b, 2, 120, 65, [120])
    t = Builder()
    P(t, [('… that on the Day of Judgement, first of all, the question will be asked about prayer itself. Prayer has been declared the pillar of the religion and also the key to Paradise. Offering prayer at the appointed time and bringing regularity into it is a very great good fortune.', 'ارشادِ گرامی بھی ہے کہ قیامت کے دن سب سے پہلے نماز ہی کے بارے میں سوال کیا جائے گا۔ نماز کو دین کا ستون اور جنت کی کنجی بھی قرار دیا گیا ہے۔ نماز وقتِ مقررہ پر ادا کرنا اور اس میں باقاعدگی لانا بہت بڑی سعادت ہے۔', '… چې د قیامت په ورځ به تر ټولو مخکې د لمانځه په اړه پوښتنه کېږي. لمونځ د دین ستن او د جنت کیلي هم ګڼل شوې. په ټاکلي وخت لمونځ ادا کول او په کې منظم والی راوستل ډېر لوی سعادت دی.'),
          ('Doing good to parents is the duty of children — especially when they reach old age, then serving them and bearing even an unpleasant word of theirs with a cheerful face is the duty of children. We should serve our parents well, and if they are not in this world, then do good deeds for the conveyance of reward (isal-e-thawab) to them. Righteous children too have been called a continuing charity (sadaqa jariya) for the parents.', 'والدین کے ساتھ نیکی کرنا اولاد کا فرض ہے۔ خاص طور پر جب وہ بڑھاپے کو پہنچ جائیں تو ان کی خدمت کرنا اور ان کی کسی ناگوار بات کو بھی خندہ پیشانی سے برداشت کرنا اولاد کا فرض ہے۔ ہمیں چاہیے کہ ہم اپنے والدین کی خوب خدمت کریں اور اگر وہ اس دنیا میں نہیں رہے تو ان کے ایصالِ ثواب کے لیے نیک کام کریں۔ نیک اولاد کو بھی والدین کے لیے صدقۂ جاریہ کہا گیا ہے۔', 'له مور و پلار سره نېکي د اولاد فرض دی. په ځانګړي ډول کله چې زړښت ته ورسېږي، نو خدمت یې کول او حتی د هغوی ناخوښه خبره په ورین تندي زغمل د اولاد فرض دی. موږ باید د خپل مور و پلار ښه خدمت وکړو، او که په دې نړۍ کې نه وي، نو د هغوی د ایصال ثواب لپاره نېک کارونه وکړو. نېک اولاد هم د مور و پلار لپاره صدقه جاریه بلل شوی.'),
          ('Striving in the way of Allah is a very great virtue. In the Quran and Hadith very great excellence of jihad has been stated. Jihad is the sixth pillar of Islam, and for those who strive, rewards and honours have been promised.', 'اللہ کے راستے میں جہاد کرنا بہت بڑی نیکی ہے۔ قرآن و حدیث میں جہاد کی بہت بڑی فضیلت بیان کی گئی ہے۔ جہاد اسلام کا چھٹا رکن ہے اور جہاد کرنے والوں کے لیے انعام و اکرام کا وعدہ کیا گیا ہے۔', 'د الله په لاره کې جهاد ډېره لویه نېکي ده. په قرآن او حدیث کې د جهاد ډېر لوی فضیلت بیان شوی. جهاد د اسلام شپږم رکن دی، او جهاد کوونکو ته د انعام او اکرام ژمنه شوې.')])
    t.h('Hadith no. 29', 'حدیث نمبر 29', 'حدیث نمبر ۲۹')
    AR(t, 'وَعَنْ اَبِي الدَّرْدَآءِ رَضِيَ اللّٰهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ قَالَ مَنْ رَدَّ عَنْ عِرْضِ اَخِيْهِ بِالْغَيْبِ رَدَّ اللّٰهُ عَنْ وَجْهِهِ النَّارَ يَوْمَ الْقِيٰمَةِ', 'الترمذی')
    t.p('Translation: It is narrated from Abu al-Darda\' (may Allah be pleased with him) that the Noble Prophet ﷺ said: whoever defends the honour of his brother when he is not present, Allah the Exalted will remove the fire from his face on the Day of Judgement.', 'ترجمہ: ابوالدرداءؓ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وآلہٖ وسلم نے فرمایا جو شخص اپنے بھائی کی عزت کا دفاع اس کے موجود نہ ہونے کے وقت کرے گا اللہ تعالیٰ قیامت کے دن اس کے چہرے سے آگ کو ہٹا دے گا۔', 'ژباړه: له ابو الدرداء رضي الله عنه روایت دی چې نبي کریم ﷺ وفرمایل: څوک چې د خپل ورور د عزت دفاع د هغه د نه شتون پر مهال وکړي، الله تعالی به د قیامت په ورځ د هغه له مخ اور لرې کړي.')
    t.h('Explanation', 'تشریح', 'تشریح')
    t.p('(1) Stopping backbiting is obligatory: just as backbiting is unlawful, in the same way listening to backbiting too is unlawful. On the Day of Judgement, just as account will be taken of the deeds of the tongue, in the same way account will be taken of the deeds of the ears too. The saying of Allah the Exalted is: "Indeed the ear, the eye and the heart — about each of them it will be asked." (Bani Isra\'il 17:36)', '(۱) غیبت سے روکنا فرض ہے: جس طرح غیبت کرنا، حرام ہے اسی طرح غیبت سننا بھی حرام ہے قیامت کے دن جس طرح زبان کے اعمال پر باز پرس ہوگی اسی طرح کانوں کے عمل پر بھی باز پرس ہوگی۔ اللہ تعالیٰ کا ارشاد ہے۔ ”یقیناً کان، آنکھ اور دل ہر ایک کے متعلق سوال کیا جائے گا“ (بنی اسرائیل ۱۷:۳۶)', '(۱) له غیبت منع کول فرض دي: لکه څنګه چې غیبت کول حرام دي، همداسې د غیبت اورېدل هم حرام دي. د قیامت په ورځ لکه څنګه چې د ژبې د عملونو پوښتنه کېږي، همداسې به د غوږونو د عمل پوښتنه هم کېږي. د الله تعالی ارشاد دی: «یقیناً د غوږ، سترګې او زړه — د هر یوه په اړه به پوښتنه کېږي.» (بني اسرائیل ۱۷:۳۶)')
    t.p('If in some gathering some person is backbiting some Muslim brother and heating up the gathering by spoiling his honour, then it is the duty of the other brothers to stop him from this vile act. By virtue of this defence, Allah the Exalted on the Day of Judgement will (remove the fire) from his face …', 'اگر کسی مجلس میں کوئی شخص کسی مسلم بھائی کی غیبت کر رہا ہو اس کی عزت کو خراب کر کے مجلس گرم کر رہا ہو۔ تو دوسرے بھائیوں کا فرض ہے کہ اسے اس شنیع فعل سے روک دیں اس دفاع کی بدولت اللہ تعالیٰ قیامت کے دن اس کے چہرے', 'که په کومه غونډه کې څوک د کوم مسلمان ورور غیبت کوي او د هغه د عزت په خرابولو غونډه ګرموي، نو د نورو وروڼو فرض دی چې هغه له دې ناوړه عمل منع کړي. د دې دفاع په برکت به الله تعالی د قیامت په ورځ د هغه له مخ …')
    BOOK.save(65, [(2, r1), (2, rec(t, 2, 121, 65, [121]))], issues=[{'id': 'iski12-pdf065', 'unit': 2, 'printedPage': 120,
               'description': 'p.121 states "جہاد اسلام کا چھٹا رکن ہے" — kept as printed. Hadith 28 reference printed "(صحیح البخاری کتاب الادب حدیث نمبر ۵۹۷۰)". Student handwriting in the margin of p.121 excluded.'}])


if __name__ == '__main__':
    p65()
